const w=(id:string,level:CEFR,title:string,topic:string,prompt:string,minWords:number,checks:[string,string,string],usefulPhrases:string[],model:string,modelTranslation:string,tip:string):WritingTask=>({id,level,title,topic,prompt,minWords,checks,usefulPhrases,model,modelTranslation,tip});
